import { axialToPixel, type AxialCoord } from "./hex.ts";

export interface CameraState {
  center: AxialCoord;
  zoom: number;
  viewportWidth: number;
  viewportHeight: number;
}

export function createCameraState(state: Partial<CameraState> = {}): CameraState {
  return {
    center: state.center ?? { q: 0, r: 0 },
    zoom: state.zoom ?? 1,
    viewportWidth: state.viewportWidth ?? 0,
    viewportHeight: state.viewportHeight ?? 0,
  };
}

export function frameCameraToPoint(point: AxialCoord, radius: number, viewportWidth: number, viewportHeight: number) {
  return createCameraState({
    center: point,
    zoom: 1,
    viewportWidth,
    viewportHeight,
  });
}

export function frameCameraToEntities(params: {
  entities: AxialCoord[];
  viewportWidth: number;
  viewportHeight: number;
  radius: number;
  padding?: number;
}) {
  const { entities, viewportWidth, viewportHeight, radius, padding = radius * 4 } = params;

  if (!entities.length) {
    return createCameraState({
      center: { q: 0, r: 0 },
      zoom: 1,
      viewportWidth,
      viewportHeight,
    });
  }

  const points = entities.map((entity) => axialToPixel(entity, radius));
  const minX = Math.min(...points.map((point) => point.x));
  const maxX = Math.max(...points.map((point) => point.x));
  const minY = Math.min(...points.map((point) => point.y));
  const maxY = Math.max(...points.map((point) => point.y));
  const spanX = Math.max(maxX - minX + padding * 2, radius * 8);
  const spanY = Math.max(maxY - minY + padding * 2, radius * 8);
  const zoomX = viewportWidth > 0 ? viewportWidth / spanX : 1;
  const zoomY = viewportHeight > 0 ? viewportHeight / spanY : 1;

  return createCameraState({
    center: {
      q: Math.round(entities.reduce((sum, entity) => sum + entity.q, 0) / entities.length),
      r: Math.round(entities.reduce((sum, entity) => sum + entity.r, 0) / entities.length),
    },
    zoom: Math.min(zoomX, zoomY, 1),
    viewportWidth,
    viewportHeight,
  });
}


export function visibleCells(params: {
  cells: { id: string; center: { x: number; y: number } }[];
  camera: CameraState;
  radius: number;
  padding?: number;
}) {
  const { cells, camera, radius, padding = radius * 2 } = params;
  const zoom = Math.max(camera.zoom, 0.0001);
  const center = axialToPixel(camera.center, radius);
  const halfWidth = camera.viewportWidth / (2 * zoom) + padding;
  const halfHeight = camera.viewportHeight / (2 * zoom) + padding;
  const minX = center.x - halfWidth;
  const maxX = center.x + halfWidth;
  const minY = center.y - halfHeight;
  const maxY = center.y + halfHeight;

  return cells.filter((cell) => {
    const pixel = cell.center;
    return pixel.x >= minX && pixel.x <= maxX && pixel.y >= minY && pixel.y <= maxY;
  });
}
